final queue = Queue<Msg>();

void enqueue(Msg msg) {
  queue.add(msg);
  _activityWake?.complete();
  _activityWake = null;
}

// [send] pushes to [_msgs]; bridge it into the same queue as stdin/ticks.
// Without this listener, async side-effects (e.g. HTTP progress/completion)
// never reach [applyMsg].
final StreamSubscription<Msg> externalMsgSub = _msgs.stream.listen(
  (Msg msg) {
    if (_running) {
      enqueue(msg);
    }
  },
);

Future<void> waitForActivity() async {
  while (_running && queue.isEmpty) {
    _activityWake = Completer<void>();
    await _activityWake!.future;
  }
}

Future<void> runCmd(Cmd? cmd) async {
  if (cmd == null || !_running) return;
  try {
    final msg = await Future<Msg?>.value(cmd());
    if (msg != null) enqueue(msg);
  } catch (e, st) {
    // Log and KEEP RUNNING: InterruptMsg here stopped the whole
    // program, and a stopped program silently drops every later
    // `send` — the CLI kept running its agent loop against a dead
    // screen (the gh-1248 mail-wake ghost: turns persisted to the
    // session while nothing painted ever again). Only a deliberate
    // QuitMsg / external cancellation ends the program.
    if (!_disableCatchPanics) {
      stderr.writeln('Caught command exception: $e');
      stderr.writeln(st);
    }
  }
}

final minFrameMicros = _fps > 0 ? (1000000 / _fps).round() : 0;
final frameClock = Stopwatch()..start();
var lastRenderMicros = -1;
var redrawArmed = false;
View? lastRenderedView;
// Keypress→paint trace sink: injected via [withTracer] or the
// FA_TUI_TRACE env file path. Zero cost when neither is set.
final tracer = _tracer ??= switch (Platform.environment['FA_TUI_TRACE']) {
  final String path? => FileFrameTracer(File(path)),
  _ => null,
};
// Frame throttle WITHOUT blocking the event loop. The old inline
// Future.delayed stalled message pickup behind every early frame (a key
// press arriving mid-frame waited out the remaining budget): with the
// spinner ticking at 10 Hz and output flushing at 20 Hz, keystrokes
// routinely queued behind ~16 ms sleeps and every interaction felt
// rubber-banded. Instead an early frame is DROPPED and one timer defers
// a RenderTickMsg; the loop keeps draining messages meanwhile and paints
// the LATEST view when the tick lands. Renders still happen strictly in
// this awaited sequence, so frames can never paint out of order or race.
//
// The view is built LAZILY: dropped frames never pay for `model.view()`
// — the old eager call site assembled the whole screen string upstream
// only to throw it away.
// Exception policy lives in [renderGuarded] below (gh-1197 self-heal +
// loud initial-frame death); render() itself stays a raw paint.
Future<void> render(View Function() buildView, {bool force = false}) async {
  final nowMicros = frameClock.elapsedMicroseconds;
  if (lastRenderMicros >= 0 && minFrameMicros > 0 && !force) {
    final delta = nowMicros - lastRenderMicros;
    if (delta < minFrameMicros) {
      debugFramesDropped++;
      tracer?.event({'t': nowMicros, 'ev': 'drop'});
      if (!redrawArmed) {
        redrawArmed = true;
        Timer(Duration(microseconds: minFrameMicros - delta), () {
          redrawArmed = false;
          if (_running) enqueue(const RenderTickMsg());
        });
      }
      return;
    }
  }
  final buildStart = frameClock.elapsedMicroseconds;
  final v = buildView();
  final buildUs = frameClock.elapsedMicroseconds - buildStart;
  final renderStart = frameClock.elapsedMicroseconds;
  _renderer?.render(v);
  final renderUs = frameClock.elapsedMicroseconds - renderStart;
  debugFramesPainted++;
  lastRenderedView = v;
  lastRenderMicros = frameClock.elapsedMicroseconds;
  tracer?.event({
    't': frameClock.elapsedMicroseconds,
    'ev': 'paint',
    'build_us': buildUs,
    'render_us': renderUs,
  });
}

// gh-1197 AC3: a throwing view()/renderer must never kill painting —
// the run continues underneath and a dead pipeline looks exactly like
// the silent freeze (no bytes for minutes, then the teardown burst).
// The guard logs loudly (same convention as the update()/runCmd()
// guards), invalidates the renderer so the NEXT frame is one full
// repaint from clean state (a mid-frame throw can strand partial
// diff state, e.g. an unclosed BSU), and schedules the repaint. The
// exception is rethrown only when NOTHING has ever painted — a
// program that cannot paint its initial screen has nothing to heal
// into, so it dies loudly instead of freezing on a blank glass.
var renderedOnce = false;
var lastRenderFailed = false;
Future<void> renderGuarded({bool force = false}) async {
  try {
    await render(_runningModel!.view, force: force);
    renderedOnce = true;
    lastRenderFailed = false;
  } catch (e, st) {
    if (!renderedOnce) rethrow;
    final repeatFailure = lastRenderFailed;
    lastRenderFailed = true;
    _renderer?.invalidate();
    lastRenderMicros = -1;
    redrawArmed = false;
    stderr
      ..writeln('Caught render exception (frame pipeline self-heals): $e')
      ..writeln(st);
    tracer?.event({
      't': frameClock.elapsedMicroseconds,
      'ev': 'render_error',
      'err': '$e',
    });
    // A repeat retry lands only on the next REAL message: re-arming
    // immediately would hot-spin a permanently throwing view through
    // catch -> RenderTick -> catch forever.
    if (_running && !repeatFailure) enqueue(const RenderTickMsg());
  }
}

void scheduleResizeMsg() {
  final width =
      _width ?? (stdout.hasTerminal ? stdout.terminalColumns : 80);
  final height =
      _height ?? (stdout.hasTerminal ? stdout.terminalLines : 24);
  enqueue(WindowSizeMsg(width, height));
}

// Process one message: update model / fire side-effects.
// Returns true when the view may have changed and a re-render is needed.
// Does NOT call render() — the event loop renders once per drained batch.
Future<bool> applyMsg(Msg rawMsg) async {
  var msg = rawMsg;
  final model = _runningModel!;
  if (_filter != null) {
    final filtered = _filter!(model, msg);
    if (filtered == null) return false;
    msg = filtered;
  }

  switch (msg) {
    case QuitMsg():
      _running = false;
      return false;
    case InterruptMsg():
      _running = false;
