  void _shutdown() {
    if (!_running && (_finished?.isCompleted ?? true)) return;
    _running = false;
    final activityWake = _activityWake;
    _activityWake = null;
    if (activityWake != null && !activityWake.isCompleted) {
      activityWake.complete();
    }
    _tickTimer?.cancel();
    _tickTimer = null;
    _loneEscTimer?.cancel();
    _loneEscTimer = null;
    unawaited(_inputSub?.cancel());
    _inputSub = null;
    unawaited(_sigSub?.cancel());
    _sigSub = null;
    _renderer?.close();
    _renderer = null;
    if (!_disableRenderer) {
      _setRawMode(false);
    }
    final logSink = _logSink;
    _logSink = null;
    if (logSink != null) {
      _logClose = logSink.close();
